const loadQuickNote = async () => {
  try {
    setQuickNoteLoading(true);
    setQuickNoteError("");

    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();

    if (userError || !user) {
      setQuickNoteError(language === "ua" ? "Увійди в desk, щоб завантажити session note." : language === "ru" ? "Войди в desk, чтобы загрузить session note." : "Enter the desk to load the session note.");
      return;
    }

    const { data, error } = await supabase
      .from("user_quick_notes")
      .select("content, updated_at")
      .eq("user_id", user.id)
      .maybeSingle();

    if (error) {
      setQuickNoteError(error.message);
      return;
    }

    setQuickNoteContent(data?.content || "");
    setQuickNoteSavedAt(data?.updated_at || "");
    setQuickNoteHydrated(true);
  } catch {
    setQuickNoteError(language === "ua" ? "Session note не завантажився. Перезайди в desk і повтори." : language === "ru" ? "Session note не загрузился. Перезайди в desk и повтори." : "Session note did not load. Re-enter the desk and retry.");
  } finally {
    setQuickNoteLoading(false);
  }
};

const saveQuickNote = async (content = quickNoteContent) => {
  try {
    setQuickNoteSaving(true);
    setQuickNoteError("");

    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();

    if (userError || !user) {
      setQuickNoteError(language === "ua" ? "Увійди в desk, щоб зберегти session note." : language === "ru" ? "Войди в desk, чтобы сохранить session note." : "Enter the desk to save the session note.");
      return;
    }

    const savedAt = new Date().toISOString();

    const { error } = await supabase.from("user_quick_notes").upsert(
      {
        user_id: user.id,
        content,
        updated_at: savedAt,
      },
      { onConflict: "user_id" }
    );

    if (error) {
      setQuickNoteError(error.message);
      return;
    }

    setQuickNoteSavedAt(savedAt);
  } catch {
    setQuickNoteError(language === "ua" ? "Session note не збережений. Перевір доступ і повтори." : language === "ru" ? "Session note не сохранён. Проверь доступ и повтори." : "Session note was not saved. Check access and retry.");
  } finally {
    setQuickNoteSaving(false);
  }
};

const handleOpenAlertsFromWidget = (assetFilter: AlertAssetFilter = "all") => {
  setRequestedAlertAssetFilter(assetFilter);
  setActiveTab("cockpit");

  if (typeof window !== "undefined") {
    const params = new URLSearchParams(window.location.search);
    params.set("tab", "signals");

    if (assetFilter === "all") {
      params.delete("assetType");
    } else {
      params.set("assetType", getAlertAssetFilterUrlValue(assetFilter));
    }

    window.history.pushState({}, "", `/dashboard?${params.toString()}`);
    window.scrollTo({ top: 0, behavior: "smooth" });
  }
};

const handleCreateTradeFromAlert = (alert: DashboardMarketAlert) => {
  setEditingTradeId("");
  setSelectedTradeIdForScreenshot("");
  setScreenshotFiles([]);
  setScreenshotError("");

  const isShort = alert.direction === "downside";
  const market = alert.asset_type === "crypto" ? "crypto" : "stocks";
  const direction = isShort ? "short" : "long";

  const entryMin =
    typeof alert.entry_zone_min === "number" ? alert.entry_zone_min : null;

  const entryMax =
    typeof alert.entry_zone_max === "number" ? alert.entry_zone_max : null;

  const entryReference =
    entryMin !== null && entryMax !== null
      ? (entryMin + entryMax) / 2
      : entryMin ?? entryMax;

  const targets = [alert.target_1, alert.target_2, alert.target_3]
    .filter((value): value is number => typeof value === "number")
    .join(" / ");

  const setupName =
    alert.setup_name || alert.setup_type || alert.title || "SkillEdge Alert";

  const draftCopy =
    language === "ua"
      ? {
          created: "Створено з сигналу SkillEdge.",
          title: "Назва сигналу",
          direction: "Напрямок",
          timeframe: "Таймфрейм",
          setup: "сетап",
          confirmation: "підтвердження",
          entry: "Зона входу",
          waitTrigger: "чекати тригер",
          stop: "Стоп",
          targets: "Цілі",
          trigger: "Тригер",
          reason: "Чому сигнал зʼявився",
          risk: "Risk",
          management: "Управління",
          invalidation: "Invalidation",
        }
      : language === "en"
        ? {
            created: "Created from SkillEdge signal plan.",
            title: "Signal title",
            direction: "Direction",
            timeframe: "Timeframe",
            setup: "setup",
            confirmation: "confirmation",
            entry: "Entry zone",
            waitTrigger: "wait for trigger",
            stop: "Stop",
            targets: "Targets",
            trigger: "Trigger",
            reason: "Why signal fired",
            risk: "Risk",
            management: "Management",
            invalidation: "Invalidation",
          }
        : {
            created: "Создано из сигнала SkillEdge.",
            title: "Название сигнала",
            direction: "Направление",
            timeframe: "Таймфрейм",
            setup: "сетап",
            confirmation: "подтверждение",
            entry: "Зона входа",
            waitTrigger: "ждать триггер",
            stop: "Стоп",
            targets: "Цели",
            trigger: "Триггер",
            reason: "Почему появился сигнал",
            risk: "Risk",
            management: "Управление",
            invalidation: "Invalidation",
          };

  const notes = [
    draftCopy.created,
    `${draftCopy.title}: ${alert.title}`,
    `${draftCopy.direction}: ${direction}`,
    `${draftCopy.timeframe}: ${alert.setup_timeframe || "5m"} ${draftCopy.setup} / ${
      alert.confirmation_timeframe || "10m"
    } ${draftCopy.confirmation}`,
    `${draftCopy.entry}: ${
      entryMin !== null && entryMax !== null
        ? `${entryMin}–${entryMax}`
        : draftCopy.waitTrigger
    }`,
    `${draftCopy.stop}: ${alert.stop_price || "—"}`,
    `${draftCopy.targets}: ${targets || "—"}`,
    alert.trigger_label ? `${draftCopy.trigger}: ${alert.trigger_label}` : null,
    alert.why_signal_fired ? `${draftCopy.reason}: ${alert.why_signal_fired}` : null,
    alert.risk_note ? `${draftCopy.risk}: ${alert.risk_note}` : null,
    alert.management_plan ? `${draftCopy.management}: ${alert.management_plan}` : null,
    alert.invalidation ? `${draftCopy.invalidation}: ${alert.invalidation}` : null,
  ]
    .filter(Boolean)
    .join("\n");

  setTradeDraftAlert(alert);

  setTradeForm({
    ticker: alert.symbol || "",
    market,
    direction,
    entryPrice: entryReference !== null ? String(Number(entryReference.toFixed(4))) : "",
    exitPrice: "",
    stopLoss: alert.stop_price ? String(alert.stop_price) : "",
    positionSize: "",
    riskAmount: "",
    pnl: "",
    result: "",
    setup: setupName,
    strategyId: "",
    strategyVersionId: "",
    setupId: alert.setup_slug || "",
    strategyExperimentId: "",
    emotion: "",
    mistake: "",
    lesson: alert.lesson_summary || "",
    notes,
    tradeDate: new Date().toISOString().slice(0, 10),
  });

  setActiveTab("journal");
  updateDashboardUrlTab("journal");

  window.setTimeout(() => {
    const target = document.getElementById("journal-add-trade");

    if (target) {
      target.scrollIntoView({
        behavior: "smooth",
        block: "start",
      });
    } else {
      window.scrollTo({ top: 0, behavior: "smooth" });
    }
  }, 180);
};

