const getActiveTabRequiredPlan = (tabId: TabId): "edge" | "elite" | null => {
  if (tabId === "edge" && !canUseFeature(subscription.plan, "personal_edge")) {
    return "edge";
  }

  if (tabId === "strategy" && !canUseFeature(subscription.plan, "strategy_os")) {
    return "edge";
  }

  if (tabId === "learning" && !canUseFeature(subscription.plan, "learning_playbook")) {
    return "edge";
  }

  if (tabId === "reports" && !canUseFeature(subscription.plan, "ai_reports")) {
    return "edge";
  }

  if (tabId === "market" && !canUseFeature(subscription.plan, "ai_scanner")) {
    return "edge";
  }

  if ((tabId === "alerts" || tabId === "cockpit") && !canUseFeature(subscription.plan, "ai_alerts")) {
    return "elite";
  }

  return null;
};
const getTabRequiredPlanLabel = (tabId: TabId) => {
  if (!subscription.active) return "";

  const requiredPlan = getActiveTabRequiredPlan(tabId);

  if (requiredPlan === "edge") {
    return "Edge";
  }

  if (requiredPlan === "elite") {
    return "Elite";
  }

  return "";
};

