  async function handleBuildStrategy(template?: StrategySetupTemplate | null) {
    const sourceTemplate = template || selectedTemplate || firstTemplate;

    if (!sourceTemplate) {
      setStrategyActionError(actionCopy.noTemplate);
      return;
    }

    const existingStrategy = getExistingStrategyForSetup(sourceTemplate.slug);

    if (existingStrategy) {
      handleSelectStrategy(existingStrategy);
      setStrategyLibraryOpen(false);
      setStrategyActionError("");
      setStrategyActionMessage(strategyLibraryCopy.createdAlready);
      return;
    }

    const title = getStrategyTemplateTitle(
      sourceTemplate.slug,
      sourceTemplate.title_i18n,
      sourceTemplate.slug.replace(/_/g, " ")
    );

    try {
      setStrategyActionLoading(`build:${sourceTemplate.slug}`);
      setStrategyActionError("");
      setStrategyActionMessage("");

      const response = await authFetch("/api/strategy/strategies", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          setupSlug: sourceTemplate.slug,
          title,
          market: sourceTemplate.market || "stocks",
          direction: sourceTemplate.direction || "both",
          style: sourceTemplate.category || "intraday",
          description: getStrategyI18nText(
            sourceTemplate.description_i18n,
            language,
            "Strategy created from SkillEdge Setup Playbook Library."
          ),
        }),
      });

      const result = await response.json().catch(() => ({}));

      if (!response.ok) {
        throw new Error(result.error || actionCopy.actionFailed);
      }

      const createdStrategyId = String(result.strategy?.id || result.data?.id || result.id || "");

      setSelectedTemplateSlug(sourceTemplate.slug);
      if (createdStrategyId) {
        setSelectedStrategyId(createdStrategyId);
      }
      setStrategyLibraryOpen(false);
      setStrategyActionMessage(actionCopy.created);
      await onRefresh();
    } catch (error) {
      setStrategyActionError(
        error instanceof Error ? error.message : actionCopy.actionFailed
      );
    } finally {
      setStrategyActionLoading("");
    }
  }

  const buildCustomStrategySlug = (title: string) => {
    const base = title
      .trim()
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "_")
      .replace(/^_+|_+$/g, "")
      .slice(0, 54);

    return `custom_${base || "strategy"}`;
  };

  async function handleCreateCustomStrategy() {
    const title = customStrategyDraft.title.trim();

    if (!title) {
      setStrategyActionError(strategyLibraryCopy.titleRequired);
      return;
    }

    const customSlug = buildCustomStrategySlug(title);
    const existingStrategy = getExistingStrategyForSetup(customSlug);

    if (existingStrategy) {
      handleSelectStrategy(existingStrategy);
      setCustomStrategyOpen(false);
      setStrategyLibraryOpen(false);
      setStrategyActionError("");
      setStrategyActionMessage(strategyLibraryCopy.createdAlready);
      return;
    }

    const linkedTemplate =
      templates.find((template) => template.slug === customStrategyDraft.linkedSetupSlug) ||
      selectedTemplate ||
      firstTemplate;

    const description = [
      strategyLibraryCopy.customText,
      `${strategyLibraryCopy.linkedSetup}: ${
        linkedTemplate
          ? getStrategyTemplateTitle(linkedTemplate.slug, linkedTemplate.title_i18n, linkedTemplate.slug.replace(/_/g, " "))
          : "—"
      }`,
      `${strategyLibraryCopy.context}: ${customStrategyDraft.contextRules}`,
      `${strategyLibraryCopy.entry}: ${customStrategyDraft.entryRules}`,
      `${strategyLibraryCopy.stop}: ${customStrategyDraft.stopRules}`,
      `${strategyLibraryCopy.targets}: ${customStrategyDraft.targetRules}`,
      `${strategyLibraryCopy.avoid}: ${customStrategyDraft.avoidRules}`,
      `${strategyLibraryCopy.checklist}: ${customStrategyDraft.checklist}`,
      `${strategyLibraryCopy.notes}: ${customStrategyDraft.notes}`,
    ]
      .filter((line) => line.replace(/.*:\s*/, "").trim().length > 0)
      .join("\n");

    try {
      setStrategyActionLoading(`build:${customSlug}`);
      setStrategyActionError("");
      setStrategyActionMessage("");

      const response = await authFetch("/api/strategy/strategies", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          setupSlug: customSlug,
          title,
          market: customStrategyDraft.market || linkedTemplate?.market || "stocks",
          direction: customStrategyDraft.direction || linkedTemplate?.direction || "both",
          style: customStrategyDraft.style || linkedTemplate?.category || "intraday",
          description,
          customRules: {
            linkedSetupSlug: linkedTemplate?.slug || null,
            contextRules: customStrategyDraft.contextRules,
            entryRules: customStrategyDraft.entryRules,
            stopRules: customStrategyDraft.stopRules,
            targetRules: customStrategyDraft.targetRules,
            avoidRules: customStrategyDraft.avoidRules,
            checklist: customStrategyDraft.checklist,
            notes: customStrategyDraft.notes,
          },
        }),
      });

      const result = await response.json().catch(() => ({}));

      if (!response.ok) {
        throw new Error(result.error || actionCopy.actionFailed);
      }

      const createdStrategyId = String(result.strategy?.id || result.data?.id || result.id || "");

      setSelectedTemplateSlug(linkedTemplate?.slug || selectedTemplateSlug);
      if (createdStrategyId) {
        setSelectedStrategyId(createdStrategyId);
      }

      setCustomStrategyOpen(false);
      setStrategyLibraryOpen(false);
      setStrategyActionMessage(strategyLibraryCopy.customCreated);
      setCustomStrategyDraft((current) => ({
        ...current,
        title: "",
        contextRules: "",
        entryRules: "",
        stopRules: "",
        targetRules: "",
        avoidRules: "",
        checklist: "",
        notes: "",
      }));
      await onRefresh();
    } catch (error) {
      setStrategyActionError(
        error instanceof Error ? error.message : actionCopy.actionFailed
      );
    } finally {
      setStrategyActionLoading("");
    }
  }

