  function openExampleForm(
    template?: StrategySetupTemplate | null,
    event?: React.MouseEvent<HTMLElement>
  ) {
    if (template?.slug) {
      setSelectedTemplateSlug(template.slug);
    }

    if (typeof window !== "undefined" && event?.currentTarget) {
      const rect = event.currentTarget.getBoundingClientRect();
      const preferredTop = Math.max(18, rect.top - 18);
      const availableHeight = Math.max(520, Math.min(window.innerHeight - preferredTop - 18, Math.round(window.innerHeight * 0.82)));

      setExampleModalTop(preferredTop);
      setExampleModalMaxHeight(availableHeight);
    } else if (typeof window !== "undefined") {
      const fallbackTop = Math.max(24, Math.round(window.innerHeight * 0.18));

      setExampleModalTop(fallbackTop);
      setExampleModalMaxHeight(Math.max(560, Math.min(window.innerHeight - fallbackTop - 18, Math.round(window.innerHeight * 0.82))));
    } else {
      setExampleModalTop(120);
      setExampleModalMaxHeight(680);
    }

    setQualityMenuOpen(false);
    setStrategyActionError("");
    setStrategyActionMessage("");
    setExampleModalOpen(true);
  }

