                <button type="button" onClick={openAfterTradeDebrief} disabled={!currentStrategy} className="rounded-full border border-violet-200/16 bg-violet-200/[0.07] px-4 py-2.5 text-[14px] font-black text-violet-100/78 transition hover:bg-violet-200/[0.11] disabled:cursor-not-allowed disabled:opacity-50">{commandCopy.afterDebrief}</button>
