function getPersonalEdgeScore(alert: DashboardMarketAlert) {
  const rawScore = alert.personal_edge_match_score;

  if (typeof rawScore !== "number" || !Number.isFinite(rawScore)) {
    return null;
  }

  return Math.max(0, Math.min(100, Math.round(rawScore)));
}

function getPersonalEdgeStatusLabel(alert: DashboardMarketAlert) {
  return String(
    alert.personal_edge_status ||
      alert.signal_mode_label ||
      alert.signal_mode ||
      "watchlist"
  )
    .replaceAll("_", " ")
    .toUpperCase();
}

function getPersonalEdgeReason(alert: DashboardMarketAlert) {
  return (
    alert.matched_fingerprint_name ||
    alert.personal_edge_label ||
    alert.personal_edge_reason ||
    alert.personal_priority_label ||
    alert.journal_pattern_name ||
    null
  );
}

function getPersonalEdgeRiskSummary(alert: DashboardMarketAlert, language: Language) {
  const copy = getPersonalEdgeCopy(language);
  const warnings = Array.isArray(alert.personal_rule_warnings)
    ? alert.personal_rule_warnings.filter(Boolean)
    : [];

  if (warnings.length > 0) {
    return `${warnings.length} ${copy.rulesNeedConfirmation}`;
  }

  if (
    typeof alert.personal_edge_anti_setup_risk_score === "number" &&
    Number.isFinite(alert.personal_edge_anti_setup_risk_score)
  ) {
    const score = Math.round(alert.personal_edge_anti_setup_risk_score);

    if (score >= 70) return copy.highRisk;
    if (score >= 45) return copy.activeRisk;
  }

  if (alert.personal_edge_risk_guard_note) {
    return copy.checkRules;
  }

  return null;
}

function getPersonalEdgePanelClass(alert: DashboardMarketAlert) {
  const riskScore =
    typeof alert.personal_edge_anti_setup_risk_score === "number"
      ? alert.personal_edge_anti_setup_risk_score
      : 0;

  const score = getPersonalEdgeScore(alert) || 0;

  if (riskScore >= 70) {
    return "border-[#FF5A5F]/20 bg-[#FF5A5F]/[0.07]";
  }

  if (score >= 80) {
    return "border-[#00C076]/22 bg-[#00C076]/[0.075]";
  }

  if (score >= 60) {
    return "border-[#C8A96B]/22 bg-[#C8A96B]/[0.075]";
  }

  return "border-white/10 bg-white/[0.035]";
}

function PersonalEdgeSignalPanel({
  alert,
  language,
  compact = false,
}: {
  alert: DashboardMarketAlert;
  language: Language;
  compact?: boolean;
}) {
  const copy = getPersonalEdgeCopy(language);
  const score = getPersonalEdgeScore(alert);
  const reason = getPersonalEdgeReason(alert);
  const riskSummary = getPersonalEdgeRiskSummary(alert, language);
  const hasPersonalEdge =
    score !== null ||
    Boolean(reason) ||
    Boolean(riskSummary) ||
    Boolean(alert.personal_edge_reason);

  if (!hasPersonalEdge) {
    return null;
  }

  return (
    <div
      className={`rounded-2xl border ${getPersonalEdgePanelClass(alert)} ${
        compact ? "p-3" : "p-4"
      }`}
    >
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div>
          <div className="text-[10px] font-black uppercase tracking-[0.22em] text-[#DFFFEF]/70">
            {copy.label}
          </div>

          <div className={`${compact ? "mt-1 text-lg" : "mt-1 text-2xl"} font-black tracking-[-0.03em] text-white`}>
            {score !== null ? `${score}% ${copy.matchSuffix}` : copy.profile}
          </div>
        </div>

        <span className="rounded-full border border-[#C8A96B]/22 bg-[#C8A96B]/10 px-3 py-1 text-[10px] font-black uppercase tracking-[0.14em] text-[#F4E8C8]">
          {getPersonalEdgeStatusLabel(alert)}
        </span>
      </div>

      {reason ? (
        <div className={compact ? "mt-2 rounded-xl border border-white/10 bg-[#07111F]/30 px-3 py-2" : "mt-3 rounded-xl border border-white/10 bg-[#07111F]/36 px-3 py-2"}>
          <div className="text-[10px] font-black uppercase tracking-[0.18em] text-white/35">
            {copy.fingerprint}
          </div>
          <div className={compact ? "mt-1 text-[13px] font-black leading-5 text-[#F4E8C8]" : "mt-1 text-sm font-black leading-5 text-[#F4E8C8]"}>
            {reason}
          </div>
        </div>
      ) : null}

      {!compact && alert.personal_edge_reason ? (
        <p className="mt-3 text-sm font-semibold leading-6 text-white/62">
          {String(alert.personal_edge_reason).includes("No high-confidence")
            ? getAlertUiCopy(language).standardAlertNote
            : alert.personal_edge_reason}
        </p>
      ) : null}

      {riskSummary ? (
        <div
          className={
            compact
              ? "mt-2 text-[12px] font-bold leading-5 text-[#FFD7D9]"
              : "mt-3 rounded-xl border border-[#FF5A5F]/18 bg-[#FF5A5F]/[0.08] px-3 py-2 text-sm font-bold leading-5 text-[#FFD7D9]"
          }
        >
          <span className="text-[#FF8A8E]">{copy.riskGuard}:</span>{" "}
          {riskSummary}
        </div>
      ) : null}

      {!compact ? (
        <div className="mt-3 grid gap-2 text-xs sm:grid-cols-3">
          <div className="rounded-xl border border-white/10 bg-black/16 p-3">
            <div className="uppercase tracking-[0.16em] text-white/30">
              {copy.profileStrength}
            </div>
            <div className="mt-1 font-black text-white/72">
              {typeof alert.personal_edge_profile_strength === "number"
                ? `${Math.round(alert.personal_edge_profile_strength)}%`
                : "—"}
            </div>
          </div>

          <div className="rounded-xl border border-white/10 bg-black/16 p-3">
            <div className="uppercase tracking-[0.16em] text-white/30">
              {copy.execution}
            </div>
            <div className="mt-1 font-black text-white/72">
              {typeof alert.personal_edge_execution_score === "number"
                ? `${Math.round(alert.personal_edge_execution_score)}%`
                : "—"}
            </div>
          </div>

          <div className="rounded-xl border border-white/10 bg-black/16 p-3">
            <div className="uppercase tracking-[0.16em] text-white/30">
              {copy.dataQuality}
            </div>
            <div className="mt-1 font-black text-white/72">
              {typeof alert.personal_edge_data_quality_score === "number"
                ? `${Math.round(alert.personal_edge_data_quality_score)}%`
                : "—"}
            </div>
          </div>
        </div>
      ) : null}
    </div>
  );
}

type AlertLifecycleBucket = "active" | "armed" | "watch";

function getAlertLifecycleBucket(alert: DashboardMarketAlert): AlertLifecycleBucket {
  const status = String(alert.status || "").toLowerCase();

  if (status === "active") return "active";
  if (status === "armed") return "armed";

  return "watch";
}

function getAlertLifecycleRankValue(alert: DashboardMarketAlert) {
  const bucket = getAlertLifecycleBucket(alert);

  if (bucket === "active") return 3;
  if (bucket === "armed") return 2;

  return 1;
}

