useEffect(() => {
  const handleCommand = (event: Event) => {
    const target = getDashboardCommandTarget(event);

    if (target === "alerts-live") {
      setAlertsWorkspace("desk");
      scrollToDashboardElement("alerts-live-command");
      return;
    }

    if (target === "alerts-outcomes") {
      setAlertsWorkspace("outcomes");
      scrollToDashboardElement("alerts-outcomes-command");
      return;
    }

    if (target === "alerts-playbook") {
      setAlertsWorkspace("playbook");
      scrollToDashboardElement("alerts-playbook-command");
    }
  };

  window.addEventListener(DASHBOARD_COMMAND_EVENT, handleCommand);
  return () => window.removeEventListener(DASHBOARD_COMMAND_EVENT, handleCommand);
}, []);

