const markSingleAlertViewed = async (alertId: string) => {
  try {
    const {
      data: { session },
    } = await supabase.auth.getSession();

    if (!session?.access_token) return;

    await authFetch("/api/market/alerts/viewed", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${session.access_token}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        alertIds: [alertId],
      }),
    });

    setAlerts((current) =>
      current.map((alert) =>
        alert.id === alertId
          ? { ...alert, is_new: false, viewed_at: new Date().toISOString() }
          : alert
      )
    );
  } catch {
    // ignore viewed state failure
  }
};

const saveAlertDecision = async (
  alertId: string,
  decision: "watching" | "taken" | "skipped" | "missed",
  decisionNote = ""
) => {
  try {
    const {
      data: { session },
    } = await supabase.auth.getSession();

    if (!session?.access_token) return;

    const response = await authFetch("/api/market/alerts/decision", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${session.access_token}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
  alertId,
  decision,
  decisionNote,
}),
    });

    if (!response.ok) return;

    setAlerts((current) =>
      current.map((alert) =>
        alert.id === alertId
          ? {
              ...alert,
              is_new: false,
              viewed_at: new Date().toISOString(),
              user_alert_decision: decision,
              user_alert_decision_note: decisionNote || alert.user_alert_decision_note || null,
            }
          : alert
      )
    );
  } catch {
    // Keep UI usable even if decision sync fails.
  }
};

const saveAlertToPlaybook = async (alert: DashboardMarketAlert) => {
  if (!hasAccess) return;

  try {
    setSavingPlaybookId(alert.id);
    setError("");

    const {
      data: { session },
    } = await supabase.auth.getSession();

    if (!session?.access_token) {
      setError("Unauthorized.");
      return;
    }

    const response = await fetch("/api/playbook/setups", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${session.access_token}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        alertId: alert.id,
      }),
    });

    const payload = await response.json().catch(() => null);

    if (!response.ok) {
      setError(payload?.error || "Failed to save setup to playbook.");
      return;
    }

    setSavedPlaybookAlertIds((current) =>
      Array.from(new Set([...current, alert.id]))
    );
    if (playbookOpen) {
  await loadPersonalPlaybook();
}
  } catch {
    setError("Failed to save setup to playbook.");
  } finally {
    setSavingPlaybookId("");
  }
};

useEffect(() => {
  setSignalAssetFilter(requestedAssetFilter);
}, [requestedAssetFilter]);

const handleSignalAssetFilterChange = (nextFilter: AlertAssetFilter) => {
  setSignalAssetFilter(nextFilter);
  onRequestedAssetFilterChange(nextFilter);
  setAlertFilter("all");

  try {
    window.localStorage.setItem("skilledge_alert_asset_filter", nextFilter);

    const params = new URLSearchParams(window.location.search);
    params.set("tab", "signals");

    if (nextFilter === "all") {
      params.delete("assetType");
    } else {
      params.set("assetType", getAlertAssetFilterUrlValue(nextFilter));
    }

    window.history.replaceState({}, "", `/dashboard?${params.toString()}`);
  } catch {
    // keep UI usable if URL/localStorage are unavailable
  }
};

useEffect(() => {
  if (requestedAssetFilter !== "all") return;

  try {
    const saved = window.localStorage.getItem("skilledge_alert_asset_filter");
    const normalized = normalizeAlertAssetFilter(saved);

    if (normalized !== "all") {
      setSignalAssetFilter(normalized);
      onRequestedAssetFilterChange(normalized);
    }
  } catch {
    // ignore localStorage errors
  }
}, [requestedAssetFilter, onRequestedAssetFilterChange]);

  useEffect(() => {
  if (!hasAccess) return;

  loadAlerts(false);

  const interval = window.setInterval(() => {
    loadAlerts(false);
  }, 30000);

  return () => {
    window.clearInterval(interval);
  };
}, [hasAccess, signalAssetFilter]);

useEffect(() => {
  if (!expandedAlertId) return;

  const previousOverflow = document.body.style.overflow;

  const handleKeyDown = (event: KeyboardEvent) => {
    if (event.key === "Escape") {
      setExpandedAlertId(null);
    }
  };

  document.body.style.overflow = "hidden";
  window.addEventListener("keydown", handleKeyDown);

  return () => {
    document.body.style.overflow = previousOverflow;
    window.removeEventListener("keydown", handleKeyDown);
  };
}, [expandedAlertId]);

useEffect(() => {
  setVisibleAlertsCount(5);
  setExpandedAlertId(null);
  setDecisionReasonFilter(null);
}, [alertFilter, signalAssetFilter]);

const assetFilteredAlerts = alerts.filter((alert) =>
  isAlertInAssetFilter(alert, signalAssetFilter)
);
const stocksSignalCount = alerts.filter((alert) => alert.asset_type !== "crypto").length;
const cryptoSignalCount = alerts.filter((alert) => alert.asset_type === "crypto").length;

const signalLifecycleCounts = {
  active: assetFilteredAlerts.filter((alert) => getAlertLifecycleBucket(alert) === "active").length,
  armed: assetFilteredAlerts.filter((alert) => getAlertLifecycleBucket(alert) === "armed").length,
  watch: assetFilteredAlerts.filter((alert) => getAlertLifecycleBucket(alert) === "watch").length,
};

const allSignalLifecycleCounts = {
  active: alerts.filter((alert) => getAlertLifecycleBucket(alert) === "active").length,
  armed: alerts.filter((alert) => getAlertLifecycleBucket(alert) === "armed").length,
  watch: alerts.filter((alert) => getAlertLifecycleBucket(alert) === "watch").length,
};

const workedCount = assetFilteredAlerts.filter(isAlertOutcomeWorked).length;

const failedCount = assetFilteredAlerts.filter(isAlertOutcomeFailed).length;

const neutralCount = assetFilteredAlerts.filter(isAlertOutcomeNeutral).length;

const pendingCount = assetFilteredAlerts.filter(isAlertOutcomePending).length;

const resolvedCount = workedCount + failedCount + neutralCount;

const qualityRate =
  resolvedCount > 0 ? Math.round((workedCount / resolvedCount) * 100) : null;

const mfeValues = assetFilteredAlerts
  .map((alert) => alert.mfe)
  .filter((value): value is number => typeof value === "number");

const maeValues = assetFilteredAlerts
  .map((alert) => alert.mae)
  .filter((value): value is number => typeof value === "number");

const avgMfe =
  mfeValues.length > 0
    ? mfeValues.reduce((sum, value) => sum + value, 0) / mfeValues.length
    : null;

const avgMae =
  maeValues.length > 0
    ? maeValues.reduce((sum, value) => sum + value, 0) / maeValues.length
    : null;

const tpHitCount = assetFilteredAlerts.filter((alert) => Boolean(alert.hit_target)).length;

const stopHitCount = assetFilteredAlerts.filter((alert) => Boolean(alert.hit_stop)).length;

const checkedOutcomeCount = assetFilteredAlerts.filter(
  (alert) => Boolean(alert.outcome_checked_at) || typeof alert.candles_checked === "number"
).length;

const entryTouchedCount = assetFilteredAlerts.filter((alert) => {
  const status = String(alert.outcome_status || "");

  return (
    status === "entry_touched" ||
    isAlertOutcomeWorked(alert) ||
    Boolean(alert.hit_target) ||
    Boolean(alert.hit_stop) ||
    typeof alert.time_to_entry_minutes === "number"
  );
}).length;

const noEntryCount = assetFilteredAlerts.filter(
  (alert) => String(alert.outcome_status || "") === "no_entry"
).length;

const entryHitRate =
  checkedOutcomeCount > 0
    ? Math.round((entryTouchedCount / checkedOutcomeCount) * 100)
    : null;

const tpHitRate =
  checkedOutcomeCount > 0
    ? Math.round((tpHitCount / checkedOutcomeCount) * 100)
    : null;

const stopRate =
  checkedOutcomeCount > 0
    ? Math.round((stopHitCount / checkedOutcomeCount) * 100)
    : null;

const noEntryRate =
  checkedOutcomeCount > 0
    ? Math.round((noEntryCount / checkedOutcomeCount) * 100)
    : null;

type SetupQualityRow = {
  setup: string;
  total: number;
  resolved: number;
  worked: number;
  failed: number;
  neutral: number;
  avgMfe: number | null;
  avgMae: number | null;
  quality: number | null;
};

const setupQualityRows = Object.values(
  assetFilteredAlerts.reduce<
    Record<string, SetupQualityRow & { mfeValues: number[]; maeValues: number[] }>
  >(
    (acc, alert) => {
      const setup =
        alert.setup_name ||
        alert.setup_type ||
        alert.setup_slug ||
        alert.title ||
        "Unknown setup";

      if (!acc[setup]) {
        acc[setup] = {
          setup,
          total: 0,
          resolved: 0,
          worked: 0,
          failed: 0,
          neutral: 0,
          avgMfe: null,
          avgMae: null,
          quality: null,
          mfeValues: [],
          maeValues: [],
        };
      }

      acc[setup].total += 1;

      if (isAlertOutcomeWorked(alert)) {
        acc[setup].worked += 1;
        acc[setup].resolved += 1;
      } else if (isAlertOutcomeFailed(alert)) {
        acc[setup].failed += 1;
        acc[setup].resolved += 1;
      } else if (isAlertOutcomeNeutral(alert)) {
        acc[setup].neutral += 1;
        acc[setup].resolved += 1;
      }

      if (typeof alert.mfe === "number") acc[setup].mfeValues.push(alert.mfe);
      if (typeof alert.mae === "number") acc[setup].maeValues.push(alert.mae);

      return acc;
    },
    {}
  )
).map((row) => ({
  ...row,
  avgMfe:
    row.mfeValues.length > 0
      ? row.mfeValues.reduce((sum, value) => sum + value, 0) / row.mfeValues.length
      : null,
  avgMae:
    row.maeValues.length > 0
      ? row.maeValues.reduce((sum, value) => sum + value, 0) / row.maeValues.length
      : null,
  quality: row.resolved > 0 ? Math.round((row.worked / row.resolved) * 100) : null,
}));

const bestOutcomeSetup =
  [...setupQualityRows]
    .filter((row) => row.resolved > 0)
    .sort(
      (a, b) =>
        (b.quality ?? -1) - (a.quality ?? -1) || b.resolved - a.resolved
    )[0] || null;

const needsCalibrationSetup =
  [...setupQualityRows]
    .filter((row) => row.resolved > 0)
    .sort(
      (a, b) =>
        (a.quality ?? 101) - (b.quality ?? 101) || b.failed - a.failed
    )[0] || null;

const signalOutcomeIntelligenceRows = assetFilteredAlerts.map((alert) => {
  const linkedTrades = trades.filter((trade) => trade.source_alert_id === alert.id);
  return {
    alert,
    intelligence: getSignalOutcomeIntelligence(alert, safeLanguage, linkedTrades),
  };
});

const signalAGradeAlerts = signalOutcomeIntelligenceRows
  .filter((row) => row.intelligence.isAPlus)
  .map((row) => row.alert);

const signalAvoidAlerts = signalOutcomeIntelligenceRows
  .filter((row) => row.intelligence.isTrash)
  .map((row) => row.alert);

const signalCleanReactionAlerts = signalOutcomeIntelligenceRows
  .filter((row) => row.intelligence.isCleanReaction)
  .map((row) => row.alert);

const signalTrapReactionAlerts = signalOutcomeIntelligenceRows
  .filter((row) => row.intelligence.isTrap)
  .map((row) => row.alert);

const lateOrSlowSignalAlerts = signalOutcomeIntelligenceRows
  .filter((row) => row.intelligence.slowEntry || row.intelligence.clientLateEntry)
  .map((row) => row.alert);

const outcomeIntelligenceCheckedCount = signalOutcomeIntelligenceRows.filter(
  (row) => row.intelligence.checked
).length;

const outcomeIntelligenceQualityScore =
  outcomeIntelligenceCheckedCount > 0
    ? Math.round(
        ((signalAGradeAlerts.length * 100 +
          signalCleanReactionAlerts.length * 70 -
          signalAvoidAlerts.length * 45 -
          signalTrapReactionAlerts.length * 35) /
          Math.max(outcomeIntelligenceCheckedCount, 1) +
          40)
      )
    : null;


type SignalSetupPerformanceRow = {
  key: string;
  strategy: string;
  setup: string;
  source: string;
  market: string;
  total: number;
  checked: number;
  resolved: number;
  worked: number;
  failed: number;
  neutral: number;
  entryTouched: number;
  tp1Hit: number;
  stopHit: number;
  noEntry: number;
  gradeA: number;
  gradeAvoid: number;
  clean: number;
  trap: number;
  avgMfe: number | null;
  avgMae: number | null;
  quality: number | null;
  entryRate: number | null;
  tpRate: number | null;
  stopRate: number | null;
  verdict: string;
  verdictTone: "strong" | "playable" | "watch" | "tighten" | "pending";
};


const normalizeSetupPerformanceIdentity = (value: string | null | undefined) =>
  String(value || "")
    .trim()
    .toLowerCase()
    .replace(/&/g, "and")
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "");

const signalCoreLibrarySource =
  safeLanguage === "en"
    ? "SkillEdge core signal library"
    : safeLanguage === "ua"
      ? "Бібліотека сигналів SkillEdge"
      : "Библиотека сигналов SkillEdge";

const signalCoreLibraryVerdict =
  safeLanguage === "en"
    ? "Waiting for outcome history"
    : safeLanguage === "ua"
      ? "Чекає історію outcomes"
      : "Ждёт историю outcomes";

