const getSetupPerformanceMatchKey = (row: Pick<SignalSetupPerformanceRow, "setup" | "strategy">) => {
  const setupIdentity = normalizeSetupPerformanceIdentity(row.setup);
  const strategyIdentity = normalizeSetupPerformanceIdentity(row.strategy);

  return setupIdentity || strategyIdentity;
};

const signalDerivedSetupPerformanceRows = Object.values(
  signalOutcomeIntelligenceRows.reduce<
    Record<
      string,
      SignalSetupPerformanceRow & {
        mfeValues: number[];
        maeValues: number[];
      }
    >
  >((acc, row) => {
    const { alert, intelligence } = row;
    const strategyLabel =
      alert.setup_name ||
      alert.setup_type ||
      alert.matched_fingerprint_name ||
      alert.journal_pattern_name ||
      alert.title ||
      "Unknown strategy";
    const setupLabel =
      alert.setup_slug ||
      alert.matched_fingerprint_slug ||
      alert.journal_pattern_name ||
      alert.setup_type ||
      "—";
    const marketLabel = alert.asset_type === "crypto" ? "Crypto" : "Stocks";
    const key = `${marketLabel}::${strategyLabel}::${setupLabel}`;

    if (!acc[key]) {
      acc[key] = {
        key,
        strategy: strategyLabel,
        setup: setupLabel,
        source: safeLanguage === "en" ? "Signal history" : safeLanguage === "ua" ? "Історія сигналів" : "История сигналов",
        market: marketLabel,
        total: 0,
        checked: 0,
        resolved: 0,
        worked: 0,
        failed: 0,
        neutral: 0,
        entryTouched: 0,
        tp1Hit: 0,
        stopHit: 0,
        noEntry: 0,
        gradeA: 0,
        gradeAvoid: 0,
        clean: 0,
        trap: 0,
        avgMfe: null,
        avgMae: null,
        quality: null,
        entryRate: null,
        tpRate: null,
        stopRate: null,
        verdict: signalPerformanceTableCopy.verdictPending,
        verdictTone: "pending",
        mfeValues: [],
        maeValues: [],
      };
    }

    acc[key].total += 1;
    if (intelligence.checked) acc[key].checked += 1;
    if (intelligence.entryTouched) acc[key].entryTouched += 1;
    if (intelligence.tp1Hit) acc[key].tp1Hit += 1;
    if (intelligence.stopHit) acc[key].stopHit += 1;
    if (intelligence.grade === "A") acc[key].gradeA += 1;
    if (intelligence.grade === "AVOID") acc[key].gradeAvoid += 1;
    if (intelligence.reaction === "clean") acc[key].clean += 1;
    if (intelligence.reaction === "trap") acc[key].trap += 1;
    if (String(alert.outcome_status || "").toLowerCase() === "no_entry") acc[key].noEntry += 1;

    if (isAlertOutcomeWorked(alert)) {
      acc[key].worked += 1;
      acc[key].resolved += 1;
    } else if (isAlertOutcomeFailed(alert)) {
      acc[key].failed += 1;
      acc[key].resolved += 1;
    } else if (isAlertOutcomeNeutral(alert)) {
      acc[key].neutral += 1;
      acc[key].resolved += 1;
    }

    if (typeof alert.mfe === "number") acc[key].mfeValues.push(alert.mfe);
    if (typeof alert.mae === "number") acc[key].maeValues.push(alert.mae);

    return acc;
  }, {})
).map((row) => {
  const avgMfeValue =
    row.mfeValues.length > 0
      ? row.mfeValues.reduce((sum, value) => sum + value, 0) / row.mfeValues.length
      : null;
  const avgMaeValue =
    row.maeValues.length > 0
      ? row.maeValues.reduce((sum, value) => sum + value, 0) / row.maeValues.length
      : null;
  const qualityValue = row.resolved > 0 ? Math.round((row.worked / row.resolved) * 100) : null;
  const entryRateValue = row.checked > 0 ? Math.round((row.entryTouched / row.checked) * 100) : null;
  const tpRateValue = row.checked > 0 ? Math.round((row.tp1Hit / row.checked) * 100) : null;
  const stopRateValue = row.checked > 0 ? Math.round((row.stopHit / row.checked) * 100) : null;

  let verdict = signalPerformanceTableCopy.verdictPending;
  let verdictTone: SignalSetupPerformanceRow["verdictTone"] = "pending";

  if (row.checked >= 3 && qualityValue !== null && qualityValue >= 70 && row.gradeA >= row.gradeAvoid) {
    verdict = signalPerformanceTableCopy.verdictStrong;
    verdictTone = "strong";
  } else if (row.checked >= 3 && qualityValue !== null && qualityValue >= 50) {
    verdict = signalPerformanceTableCopy.verdictPlayable;
    verdictTone = "playable";
  } else if (row.checked >= 3 && (qualityValue === null || qualityValue < 35 || row.gradeAvoid > row.gradeA)) {
    verdict = signalPerformanceTableCopy.verdictTighten;
    verdictTone = "tighten";
  } else if (row.checked > 0) {
    verdict = signalPerformanceTableCopy.verdictWatch;
    verdictTone = "watch";
  }

  const { mfeValues, maeValues, ...cleanRow } = row;

  return {
    ...cleanRow,
    avgMfe: avgMfeValue,
    avgMae: avgMaeValue,
    quality: qualityValue,
    entryRate: entryRateValue,
    tpRate: tpRateValue,
    stopRate: stopRateValue,
    verdict,
    verdictTone,
  };
});


const getPerformanceVerdict = (checked: number, quality: number | null, gradeA = 0, gradeAvoid = 0) => {
  let verdict = signalPerformanceTableCopy.verdictPending;
  let verdictTone: SignalSetupPerformanceRow["verdictTone"] = "pending";

  if (checked >= 3 && quality !== null && quality >= 70 && gradeA >= gradeAvoid) {
    verdict = signalPerformanceTableCopy.verdictStrong;
    verdictTone = "strong";
  } else if (checked >= 3 && quality !== null && quality >= 50) {
    verdict = signalPerformanceTableCopy.verdictPlayable;
    verdictTone = "playable";
  } else if (checked >= 3 && (quality === null || quality < 35 || gradeAvoid > gradeA)) {
    verdict = signalPerformanceTableCopy.verdictTighten;
    verdictTone = "tighten";
  } else if (checked > 0) {
    verdict = signalPerformanceTableCopy.verdictWatch;
    verdictTone = "watch";
  }

  return { verdict, verdictTone };
};

