const signalDerivedRowsBySetup = new Map<string, SignalSetupPerformanceRow>();

for (const row of signalDerivedSetupPerformanceRows) {
  const directKey = getSetupPerformanceMatchKey(row);
  const strategyKey = normalizeSetupPerformanceIdentity(row.strategy);

  if (directKey) signalDerivedRowsBySetup.set(directKey, row);
  if (strategyKey) signalDerivedRowsBySetup.set(strategyKey, row);
}

const coreSignalLibraryPerformanceRows = builtInSignalSetupLibraryRows.map((libraryRow) => {
  const librarySetupKey = normalizeSetupPerformanceIdentity(libraryRow.setup);
  const libraryStrategyKey = normalizeSetupPerformanceIdentity(libraryRow.strategy);
  const matchedRow =
    signalDerivedRowsBySetup.get(librarySetupKey) ||
    signalDerivedRowsBySetup.get(libraryStrategyKey) ||
    null;

  if (!matchedRow) return libraryRow;

  return {
    ...matchedRow,
    key: libraryRow.key,
    strategy: libraryRow.strategy,
    setup: libraryRow.setup,
    source: matchedRow.source,
    market: libraryRow.market,
  };
});

