const findAiCandidate = (symbol: string) =>
  aiPreviewItems.find(
    (candidate) =>
      candidate.symbol.toUpperCase() === String(symbol || "").toUpperCase()
  ) ||
  opportunities.find(
    (candidate) =>
      candidate.symbol.toUpperCase() === String(symbol || "").toUpperCase()
  ) ||
  null;

const getAiScoreValue = (item: MarketAIAnalysisItem) => {
  const directScore = Number(item.confluence_score ?? item.score);

  if (Number.isFinite(directScore) && directScore > 0) {
    return Math.round(directScore);
  }

  const candidate = findAiCandidate(item.symbol);
  const fallbackScore = Number(candidate?.combinedScore ?? 0);

  return Number.isFinite(fallbackScore) && fallbackScore > 0
    ? Math.round(fallbackScore)
    : null;
};

const getAiScoreLabel = (item: MarketAIAnalysisItem) => {
  const scoreValue = getAiScoreValue(item);
  return scoreValue == null ? "—" : String(scoreValue);
};

const getAiInvalidationText = (item: MarketAIAnalysisItem) => {
  const explicitInvalidation = String(item.invalidation || "").trim();

  if (explicitInvalidation) return explicitInvalidation;

  const candidate = findAiCandidate(item.symbol);
  const riskText = String(item.risk_note || candidate?.riskNote || "").trim();
  const scenarioText = String(item.scenario || "").trim();

  if (riskText) {
    return safeLanguage === "en"
      ? `Idea breaks if the listed risk confirms: ${riskText}`
      : safeLanguage === "ua"
        ? `Ідея скасовується, якщо підтверджується цей ризик: ${riskText}`
        : `Идея отменяется, если подтверждается этот риск: ${riskText}`;
  }

  if (scenarioText) {
    return safeLanguage === "en"
      ? `No trade without the scenario holding: ${scenarioText}`
      : safeLanguage === "ua"
        ? `Без угоди, якщо сценарій не утримується: ${scenarioText}`
        : `Без сделки, если сценарий не удерживается: ${scenarioText}`;
  }

  return safeLanguage === "en"
    ? "Invalidation must be defined before execution. No chase without a clean level."
    : safeLanguage === "ua"
      ? "Invalidation треба визначити до входу. Без чистого рівня — не наздоганяти рух."
      : "Отмену идеи нужно определить до входа. Без чистого уровня — не догонять движение.";
};

