        dailyPlan: "План дня",
        dailySubtitle: "Что сегодня торговать, что запрещено и какой процесс удерживать.",
        focus: "Фокус дня",
        allowed: "Разрешённые сетапы",
        forbidden: "Запрещено сегодня",
