function GlobalDashboardCommandCenter({
  activeTab,
  language,
  planLabel,
  onCommand,
}: {
  activeTab: TabId;
  language: Language;
  planLabel: string;
  onCommand: (target: string) => void;
}) {
  const copy = getGlobalCommandCopy(activeTab, language);
  const isUa = language === "ua";
  const isEn = language === "en";

  return (
    <motion.section
      initial={{ opacity: 0, y: 18 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.45, delay: 0.04 }}
      className="se-premium-shell mt-6 overflow-hidden rounded-[2.25rem] border border-[#C8A96B]/18 bg-[linear-gradient(135deg,rgba(7,17,31,0.96),rgba(15,23,42,0.92),rgba(17,28,45,0.84))] p-5 shadow-[0_24px_90px_rgba(0,0,0,0.32)]"
    >
      <div className="grid gap-5 xl:grid-cols-[0.86fr_1.14fr] xl:items-stretch">
        <div className="relative overflow-hidden rounded-[1.8rem] border border-white/10 bg-white/[0.045] p-5">
          <div className="pointer-events-none absolute -right-16 -top-20 h-40 w-40 rounded-full bg-[#00C076]/14 blur-3xl" />
          <div className="pointer-events-none absolute -bottom-20 -left-12 h-40 w-40 rounded-full bg-[#C8A96B]/12 blur-3xl" />

          <div className="relative">
            <div className="flex flex-wrap items-center gap-2">
              <span className="rounded-full border border-[#00C076]/22 bg-[#00C076]/10 px-3 py-1 text-[10px] font-black uppercase tracking-[0.22em] text-[#DFFFEF]/78">
                {copy.label}
              </span>
              <span className="rounded-full border border-[#C8A96B]/20 bg-[#C8A96B]/10 px-3 py-1 text-[10px] font-black uppercase tracking-[0.18em] text-[#F4E7C4]/72">
                {planLabel}
              </span>
            </div>

            <h2 className="mt-4 text-2xl font-black leading-[1.05] tracking-[-0.045em] text-[#E6EDF7] md:text-3xl">
              {copy.title}
            </h2>

            <p className="mt-3 max-w-2xl text-sm font-semibold leading-7 text-[#94A3B8]">
              {copy.text}
            </p>

            <div className="mt-5 rounded-[1.3rem] border border-white/10 bg-black/20 p-4 text-sm font-semibold leading-6 text-white/58">
              {isEn
                ? "Pick one desk zone. Details open only after the trader knows the job to execute."
                : isUa
                  ? "Спочатку обери одну зону. Деталі відкриваються тільки після зрозумілого вибору."
                  : "Сначала выбери рабочую зону. Детали открываются после понятного трейдерского запроса."}
            </div>
          </div>
        </div>

        <div className="grid gap-3 md:grid-cols-3">
          {copy.cards.map((card, index) => (
            <button
              key={`${card.target}-${index}-${card.title}`}
              type="button"
              onClick={() => onCommand(card.target)}
              className="se-command-card group relative min-h-[170px] overflow-hidden rounded-[1.8rem] border border-[#C8A96B]/13 bg-[#0F172A]/82 p-5 text-left transition hover:-translate-y-1 hover:border-[#C8A96B]/34 hover:bg-[#111C2D] hover:shadow-[0_24px_80px_rgba(200,169,107,0.12)]"
            >
              <div className="absolute inset-x-0 top-0 h-px bg-gradient-to-r from-transparent via-[#00D084]/40 to-transparent opacity-0 transition group-hover:opacity-100" />
              <div className="flex items-start justify-between gap-3">
                <div className="flex h-9 w-9 items-center justify-center rounded-2xl border border-[#00D084]/18 bg-[#00D084]/10 text-[11px] font-black text-[#DFFFEF]">
                  0{index + 1}
                </div>
                <span className="rounded-full border border-white/10 bg-white/[0.05] px-3 py-1 text-[10px] font-black uppercase tracking-[0.16em] text-white/46 transition group-hover:border-[#00D084]/20 group-hover:text-[#DFFFEF]">
                  {card.meta}
                </span>
              </div>

              <div className="mt-5 text-base font-black tracking-[-0.02em] text-[#E6EDF7]">
                {card.title}
              </div>

              <p className="mt-2 text-sm font-semibold leading-6 text-[#94A3B8]">
                {card.text}
              </p>

              <div className="mt-5 inline-flex items-center gap-2 text-xs font-black uppercase tracking-[0.16em] text-[#00D084]/80">
                {isEn ? "Go" : isUa ? "Перейти" : "Перейти"} <span>→</span>
              </div>
            </button>
          ))}
        </div>
      </div>
    </motion.section>
  );
}

