const strategyCopy = strategyReportsCopy[language];

const safeTextValue = (value: unknown, fallback = "—") => {
  if (typeof value === "string" && value.trim()) return value.trim();
  if (typeof value === "number" && Number.isFinite(value)) return String(value);
  return fallback;
};

const toReportScore = (value: unknown) => {
  if (typeof value === "number" && Number.isFinite(value)) {
    return Math.max(0, Math.min(100, Math.round(value)));
  }

  if (typeof value === "string" && value.trim()) {
    const parsed = Number(value);
    if (Number.isFinite(parsed)) {
      return Math.max(0, Math.min(100, Math.round(parsed)));
    }
  }

  return null;
};

const readStrategyScore = (keys: string[], fallback?: unknown) => {
  const scoreSources = [
    strategyAnalytics?.scores || {},
    strategyAnalytics?.summary || {},
    strategyAnalytics?.recent || {},
  ];

  for (const source of scoreSources) {
    const record = asRecord(source);

    for (const key of keys) {
      const score = toReportScore(record[key]);
      if (score !== null) return score;
    }
  }

  return toReportScore(fallback);
};

