const strategyLinkedTrades = filteredTrades.filter((trade) => {
  const hasStrategyLink = Boolean(
    trade.strategy_id ||
      trade.strategy_version_id ||
      trade.strategy_experiment_id ||
      trade.strategy_link_source ||
      trade.setup_id
  );

  if (!hasStrategyLink) return false;
  if (!activeStrategyId) return true;

  return (
    trade.strategy_id === activeStrategyId ||
    !trade.strategy_id ||
    trade.setup_id === activeStrategySetupSlug ||
    trade.source_setup_slug === activeStrategySetupSlug
  );
});

const strategyPnlValues = strategyLinkedTrades
